-- ════════════════════════════════════════════════════════════════════
-- Tanda 1281: las cartas nuevas del catálogo, con su ficha de juego.
--
-- IBAI: «quiero que clasifiques todas las nuevas cartas que añade la
-- colección de PokeDoc para que funcione correctamente en todo el apartado
-- de jugar».
--
-- Las cartas que crea TCGGO («tcggo-<id>») nacen con número, nombre, foto y
-- precio, pero SIN ficha: ni categoría, ni PS, ni tipo, ni fase, ni ataques,
-- ni debilidad, ni retirada. Y el engorde de TCGdex no las visita (su id no
-- existe allí: nacen con `detalle_at` puesto). El 2026-11-11 había 1.604
-- cartas occidentales sin categoría: Delta Reign entera (141), la 30th
-- Celebration entera (191), los nueve Prize Pack (1.061), 29 MEP, 20 SVP, las
-- cuatro Trainer Gallery de Espada y Escudo (109, estas de TCGdex pero con un
-- id que su API no conoce: «respuesta vacía») y unas pocas sueltas.
--
-- Sin categoría, en Jugar una carta no es Pokémon, ni Entrenador, ni
-- Energía: el constructor no la saca en los filtros, el laboratorio no la
-- puede poner en juego ni atacar con ella, las repeticiones no la reconocen
-- y la regla de la reimpresión no la encuentra. Las gemelas de la 913 solo
-- lo apañaban EN Jugar, al vuelo, y para cartas que tienen otra impresión.
--
-- Tres fuentes, de la más segura a la más amplia:
--
--   A. Las expansiones nuevas, desde tcgdex/cards-database (commit 00d5de7,
--      2026-11-09): la ficha entera de cada carta, con los textos en español
--      cuando TCGdex los tiene todos (como el engorde, que la pide en español
--      y cae a inglés) y los enums en su forma canónica inglesa. Casa por
--      set + nombre (inglés o español) + número; si el nombre es único en el
--      set de TCGdex, basta el nombre. Las que TCGGO numera o nombra a su
--      manera («AQ149 Lugia», «R/RGB Mew», «Legendary Pyroduct (Left)»,
--      «Bubbly [W] Energy») van por su número exacto, a mano.
--   B. Las reimpresiones (Prize Pack, promos repetidas, duplicados viejos),
--      COPIADAS de la impresión original que ya tenemos engordada: mismo
--      nombre y, por orden, mismo set y número; o el set de «NNN/MMM» (el que
--      tiene MMM cartas oficiales) y el número NNN; o el mismo número escrito
--      igual («SWSH111»). Si a ese nivel hay dos impresiones distintas, no se
--      elige: se queda como estaba.
--   C. Lo que queda: un Entrenador o una Energía especial cuyo nombre solo
--      existe como esa misma clase de carta (todas sus impresiones dicen lo
--      mismo), y las energías básicas por su nombre.
--
-- SOLO RELLENA LO VACÍO: cada columna con `coalesce` y solo en filas sin
-- categoría. No toca `name`, ni la foto, ni el precio, ni `detalle_lang`
-- (que marca en qué idioma está el nombre). Lo corregido a mano en /admin
-- gana igual que siempre (el disparador de la 885). Se puede ejecutar dos
-- veces: la segunda no encuentra nada que hacer.
--
-- Lo que NO hay: la marca de regulación de Delta Reign (TCGdex todavía no la
-- trae y no se inventa: esas cartas siguen contando como legales por ser de
-- una colección reciente, como hasta hoy).
--
-- Ejecutar en el SQL Editor de Supabase. Cada sentencia se sostiene sola
-- (la 631): las listas van en un `(values …)` dentro de cada una. La última
-- es un SELECT que dice lo que haya quedado sin ficha.
-- ════════════════════════════════════════════════════════════════════

-- ── A0. Las que TCGGO numera a su manera: por su número exacto ───────
update public.tcg_cards c
   set category        = coalesce(c.category, v.f->>'category'),
       hp              = coalesce(c.hp, (v.f->>'hp')::int),
       types           = coalesce(c.types, (select array_agg(t) from jsonb_array_elements_text(v.f->'types') t)),
       stage           = coalesce(c.stage, v.f->>'stage'),
       evolve_from     = coalesce(c.evolve_from, v.f->>'evolve_from'),
       retreat         = coalesce(c.retreat, (v.f->>'retreat')::int),
       attacks         = coalesce(c.attacks, v.f->'attacks'),
       abilities       = coalesce(c.abilities, v.f->'abilities'),
       weaknesses      = coalesce(c.weaknesses, v.f->'weaknesses'),
       resistances     = coalesce(c.resistances, v.f->'resistances'),
       trainer_type    = coalesce(c.trainer_type, v.f->>'trainer_type'),
       energy_type     = coalesce(c.energy_type, v.f->>'energy_type'),
       suffix          = coalesce(c.suffix, v.f->>'suffix'),
       dex_ids         = case when coalesce(cardinality(c.dex_ids), 0) = 0
                              then coalesce((select array_agg(d::int) from jsonb_array_elements_text(v.f->'dex_ids') d), c.dex_ids)
                              else c.dex_ids end,
       regulation_mark = coalesce(c.regulation_mark, v.f->>'regulation_mark'),
       illustrator     = coalesce(c.illustrator, v.f->>'illustrator'),
       description     = coalesce(nullif(c.description, ''), v.f->>'description'),
       name_es         = coalesce(c.name_es, v.f->>'name_es')
  from (values
    ('30th', 'AQ149', '{"category":"Pokemon","hp":80,"types":["Colorless"],"stage":"Basic","retreat":3,"attacks":[{"cost":["Fire","Psychic"],"name":"Psíquico","effect":"Hace 10 puntos de daño multiplicado por la cantidad de cartas de Energía unidas al Pokémon a la defensa.","damage":"10×"},{"cost":["Fire","Water","Water","Colorless"],"name":"Explosión Vapor","effect":"Descarta 1 carta de Energía unida a Lugia.","damage":50}],"weaknesses":[{"type":"Psychic","value":"×2"}],"dex_ids":[249],"illustrator":"Naoyo Kimura","name_es":"Lugia"}'::jsonb),  -- 30th Classic Collection/029
