    ('30th', 'PL047', '{"category":"Pokemon","hp":80,"types":["Psychic"],"stage":"Basic","retreat":0,"attacks":[{"cost":["Psychic","Colorless"],"name":"Colmillo tóxico","effect":"El Pokémon Defensor pasa a estar Envenenado. Pon 2 contadores de daño en vez de 1 sobre el Pokémon Defensor entre turno y turno."}],"weaknesses":[{"type":"Lightning","value":"×2"}],"resistances":[{"type":"Fighting","value":"-20"}],"dex_ids":[169],"suffix":"SP","illustrator":"Makoto Imai","name_es":"Crobat G"}'::jsonb),  -- 30th Classic Collection/011
