    ('30th', 4, 'illumise', 'illumise', true, '{"category":"Pokemon","hp":80,"types":["Grass"],"stage":"Basic","retreat":1,"attacks":[{"cost":["Grass","Colorless"],"name":"Apisonar","damage":30}],"abilities":[{"type":"Habilidad","name":"Feromonas Supereficaces","effect":"Si tienes a Volbeat en juego, aplica una Debilidad de × 3 a ambos Pokémon Activos."}],"weaknesses":[{"type":"Fire","value":"×2"}],"dex_ids":[314],"description":"It guides Volbeat to draw signs in the night sky. There are scholars who research the meaning of these signs.","regulation_mark":"J","illustrator":"Shibuzoh.","name_es":"Illumise"}'::jsonb),  -- 30th Celebration/004
    ('30th', 5, 'tropius', 'tropius', true, '{"category":"Pokemon","hp":120,"types":["Grass"],"stage":"Basic","retreat":2,"attacks":[{"cost":["Grass","Colorless"],"name":"Apoyo Vengativo","effect":"Si alguno de tus Pokémon quedó Fuera de Combate por el daño de un ataque durante el último turno de tu rival, este ataque hace 90 puntos de daño más.","damage":"30+"},{"cost":["Grass","Colorless","Colorless"],"name":"Viento Helado","damage":90}],"weaknesses":[{"type":"Fire","value":"×2"}],"dex_ids":[357],"description":"Delicious fruits grew out from around its neck because it always ate the same kind of fruit.","regulation_mark":"J","illustrator":"Minahamu","name_es":"Tropius"}'::jsonb),  -- 30th Celebration/005
    ('30th', 6, 'cherubi', 'cherubi', true, '{"category":"Pokemon","hp":40,"types":["Grass"],"stage":"Basic","retreat":1,"attacks":[{"cost":["Colorless"],"name":"Ocultarse","effect":"Lanza 1 moneda. Si sale cara, durante el próximo turno de tu rival, se evitan todo el daño y todos los efectos de los ataques infligidos a este Pokémon."},{"cost":["Grass"],"name":"Vuelta","damage":10}],"weaknesses":[{"type":"Fire","value":"×2"}],"dex_ids":[420],"description":"It nimbly dashes about to avoid getting pecked by bird Pokémon that would love to make off with its small, nutrient-rich storage ball.","regulation_mark":"J","illustrator":"Kurata So","name_es":"Cherubi"}'::jsonb),  -- 30th Celebration/006
    ('30th', 7, 'cherrim', 'cherrim', true, '{"category":"Pokemon","hp":80,"types":["Grass"],"stage":"Stage1","retreat":1,"attacks":[{"cost":["Colorless"],"name":"Regalo de Energía","effect":"Busca en tu baraja hasta 2 cartas de Energía Básica y únelas a tus Pokémon de la manera que desees. Después, baraja las cartas de tu baraja."},{"cost":["Grass","Colorless"],"name":"Follaje","damage":50}],"weaknesses":[{"type":"Fire","value":"×2"}],"dex_ids":[421],"description":"After absorbing plenty of sunlight, Cherrim takes this form. It''s full of energy while it''s like this, and its liveliness will go on until sundown.","regulation_mark":"J","illustrator":"takashi shiraishi","name_es":"Cherrim"}'::jsonb),  -- 30th Celebration/007
    ('30th', 8, 'vivillon', 'vivillon', true, '{"category":"Pokemon","hp":120,"types":["Grass"],"stage":"Stage2","retreat":1,"attacks":[{"cost":["Grass","Colorless"],"name":"Polvo Veneno","effect":"El Pokémon Activo de tu rival pasa a estar Envenenado.","damage":60}],"abilities":[{"type":"Habilidad","name":"Danza Guía","effect":"Una vez durante tu turno, puedes usar esta habilidad. Lanza 1 moneda. Si sale cara, busca en tu baraja 1 Pokémon, enséñalo y ponlo en tu mano. Después, baraja las cartas de tu baraja."}],"weaknesses":[{"type":"Fire","value":"×2"}],"dex_ids":[666],"description":"This Pokémon was born in a special land. It scatters colorful, toxic scales from its wings during battle.","regulation_mark":"J","illustrator":"Jerky","name_es":"Vivillon"}'::jsonb),  -- 30th Celebration/008
    ('30th', 9, 'vulpix', 'vulpix', true, '{"category":"Pokemon","hp":70,"types":["Fire"],"stage":"Basic","retreat":1,"attacks":[{"cost":["Fire"],"name":"Patada Salvaje","effect":"Lanza 1 moneda. Si sale cruz, este ataque no hace nada.","damage":30}],"weaknesses":[{"type":"Water","value":"×2"}],"dex_ids":[37],"description":"As its body grows larger, its six warm tails become more beautiful, with a more luxurious coat of fur.","regulation_mark":"J","illustrator":"miki kudo","name_es":"Vulpix"}'::jsonb),  -- 30th Celebration/009
