    ('swsh9.5tg', 6, 'dusknoir', 'dusknoir', true, '{"category":"Pokemon","hp":150,"types":["Psychic"],"stage":"Stage2","evolve_from":"Dusclops","retreat":2,"attacks":[{"cost":["Psychic","Colorless","Colorless"],"name":"Disparo Embrujado","damage":120}],"abilities":[{"type":"Habilidad","name":"Brecha Espectral","effect":"Todas las Energías Especiales unidas a los Pokémon (tanto tuyos como de tu rival) proporcionan 1 Energía Colorless y no tienen ningún otro efecto."}],"weaknesses":[{"type":"Darkness","value":"×2"}],"resistances":[{"type":"Fighting","value":"-30"}],"dex_ids":[477],"description":"At the bidding of transmissions from the spirit world, it steals people and Pokémon away. No one knows whether it has a will of its own.","regulation_mark":"D","illustrator":"Megumi Higuchi","name_es":"Dusknoir"}'::jsonb),  -- Brilliant Stars Trainer Gallery/TG06
