    ('swsh9.5tg', 30, 'rapidstrikeurshifuvmax', 'urshifugolpefluidovmax', false, '{"category":"Pokemon","hp":330,"types":["Fighting"],"stage":"VMAX","evolve_from":"Urshifu Golpe Fluido V","retreat":2,"attacks":[{"cost":["Fighting"],"name":"Impulso Vendaval","effect":"Si este Pokémon se ha movido de tu Banca al Puesto Activo en este turno, este ataque hace 120 puntos de daño más.","damage":"30+"},{"cost":["Fighting","Fighting","Colorless"],"name":"Gigagolpe Fluido","effect":"Descarta todas las Energías de este Pokémon. Este ataque hace 120 puntos de daño a 2 de los Pokémon de tu rival. (No apliques Debilidad y Resistencia a los Pokémon en Banca)."}],"weaknesses":[{"type":"Psychic","value":"×2"}],"dex_ids":[892],"regulation_mark":"E","illustrator":"PLANETA Tsuji","name_es":"Urshifu Golpe Fluido VMAX"}'::jsonb)  -- Brilliant Stars Trainer Gallery/TG30
  ) as v(set_id, num, k, kes, unico, f)
 where c.market = 'WEST'
   and c.set_id = v.set_id
   and c.category is null
   and regexp_replace(immutable_unaccent(lower(c.name)), '[^a-z0-9]', '', 'g') in (v.k, v.kes)
   and ((case when length(regexp_replace(c.local_id, '\D', '', 'g')) between 1 and 9 then regexp_replace(c.local_id, '\D', '', 'g')::int end) = v.num or v.unico);

-- ── A5. Astral Radiance Trainer Gallery (30) ─────────────────────────
update public.tcg_cards c
   set category        = coalesce(c.category, v.f->>'category'),
       hp              = coalesce(c.hp, (v.f->>'hp')::int),
       types           = coalesce(c.types, (select array_agg(t) from jsonb_array_elements_text(v.f->'types') t)),
       stage           = coalesce(c.stage, v.f->>'stage'),
       evolve_from     = coalesce(c.evolve_from, v.f->>'evolve_from'),
       retreat         = coalesce(c.retreat, (v.f->>'retreat')::int),
       attacks         = coalesce(c.attacks, v.f->'attacks'),
       abilities       = coalesce(c.abilities, v.f->'abilities'),
       weaknesses      = coalesce(c.weaknesses, v.f->'weaknesses'),
       resistances     = coalesce(c.resistances, v.f->'resistances'),
       trainer_type    = coalesce(c.trainer_type, v.f->>'trainer_type'),
       energy_type     = coalesce(c.energy_type, v.f->>'energy_type'),
       suffix          = coalesce(c.suffix, v.f->>'suffix'),
       dex_ids         = case when coalesce(cardinality(c.dex_ids), 0) = 0
                              then coalesce((select array_agg(d::int) from jsonb_array_elements_text(v.f->'dex_ids') d), c.dex_ids)
                              else c.dex_ids end,
       regulation_mark = coalesce(c.regulation_mark, v.f->>'regulation_mark'),
       illustrator     = coalesce(c.illustrator, v.f->>'illustrator'),
       description     = coalesce(nullif(c.description, ''), v.f->>'description'),
       name_es         = coalesce(c.name_es, v.f->>'name_es')
  from (values
    ('swsh10.5tg', 1, 'abomasnow', 'abomasnow', true, '{"category":"Pokemon","hp":140,"types":["Grass"],"stage":"Stage1","evolve_from":"Snover","retreat":3,"attacks":[{"cost":["Grass","Colorless","Colorless"],"name":"Megapuño","damage":90}],"abilities":[{"type":"Habilidad","name":"Impulso Vigorizante","effect":"Tus Pokémon Golpe Brusco en juego, excepto los Abomasnow, obtienen 50 PS más. No puedes aplicar más de 1 habilidad Impulso Vigorizante a la vez."}],"weaknesses":[{"type":"Fire","value":"×2"}],"dex_ids":[460],"description":"The Pokémon is known to bring blizzards. A shake of its massive body is enough to cause whiteout conditions.","regulation_mark":"E","illustrator":"Mitsuhiro Arita","name_es":"Abomasnow"}'::jsonb),  -- Astral Radiance Trainer Gallery/TG01
    ('swsh10.5tg', 2, 'flapple', 'flapple', true, '{"category":"Pokemon","hp":80,"types":["Grass"],"stage":"Stage1","evolve_from":"Applin","retreat":1,"attacks":[{"cost":["Colorless","Colorless"],"name":"Bomba Ácida","effect":"Lanza 1 moneda. Si sale cara, descarta 1 Energía del Pokémon Activo de tu rival.","damage":60}],"abilities":[{"type":"Habilidad","name":"Caída de Manzanas","effect":"Una vez durante tu turno, puedes poner 2 contadores de daño en 1 de los Pokémon de tu rival. Si has puesto algún contador de daño de esta manera, pon este Pokémon y todas las cartas unidas a él en tu baraja, y baraja todas las cartas."}],"weaknesses":[{"type":"Fire","value":"×2"}],"dex_ids":[841],"description":"It ate a sour apple, and that induced its evolution. In its cheeks, it stores an acid capable of causing chemical burns.","regulation_mark":"D","illustrator":"Misaki Hashimoto","name_es":"Flapple"}'::jsonb),  -- Astral Radiance Trainer Gallery/TG02
    ('swsh10.5tg', 3, 'kingdra', 'kingdra', true, '{"category":"Pokemon","hp":150,"types":["Water"],"stage":"Stage2","evolve_from":"Seadra","retreat":1,"attacks":[{"cost":["Water"],"name":"Estallido Acuático","effect":"Este ataque hace 40 puntos de daño por cada Energía Water unida a este Pokémon.","damage":"40×"}],"abilities":[{"type":"Habilidad","name":"Rey del Mar Profundo","effect":"Cuando tu Pokémon Activo queda Fuera de Combate por el daño de un ataque de los Pokémon de tu rival, puedes mover cualquier cantidad de Energías Water de ese Pokémon a este Pokémon."}],"weaknesses":[{"type":"Lightning","value":"×2"}],"dex_ids":[230],"description":"It stores energy by sleeping at underwater depths at which no other life forms can survive.","regulation_mark":"E","illustrator":"Taira Akitsu","name_es":"Kingdra"}'::jsonb),  -- Astral Radiance Trainer Gallery/TG03
    ('swsh10.5tg', 4, 'frosmoth', 'frosmoth', true, '{"category":"Pokemon","hp":90,"types":["Water"],"stage":"Stage1","evolve_from":"Snom","retreat":2,"attacks":[{"cost":["Water","Colorless"],"name":"Rayo Aurora","damage":30}],"abilities":[{"type":"Habilidad","name":"Danza Helada","effect":"Todas las veces que quieras durante tu turno, puedes unir 1 carta de Energía Water de tu mano a 1 de tus Pokémon Water en Banca."}],"weaknesses":[{"type":"Metal","value":"×2"}],"dex_ids":[873],"description":"It shows no mercy to any who desecrate fields and mountains. It will fly around on its icy wings, causing a blizzard to chase offenders away.","regulation_mark":"D","illustrator":"aoki","name_es":"Frosmoth"}'::jsonb),  -- Astral Radiance Trainer Gallery/TG04
    ('swsh10.5tg', 5, 'gardevoir', 'gardevoir', true, '{"category":"Pokemon","hp":140,"types":["Psychic"],"stage":"Stage2","evolve_from":"Kirlia","retreat":2,"attacks":[{"cost":["Colorless","Colorless","Colorless"],"name":"Onda Cerebral","effect":"Este ataque hace 30 puntos de daño más por cada Energía Psychic unida a este Pokémon.","damage":"60+"}],"abilities":[{"type":"Habilidad","name":"Arcano Radiante","effect":"Una vez durante tu turno, puedes mirar las 2 primeras cartas de tu baraja y unir cualquier cantidad de cartas de Energía Básica que encuentres entre ellas a tus Pokémon de la manera que desees. Pon el resto de las cartas en tu mano."}],"weaknesses":[{"type":"Metal","value":"×2"}],"dex_ids":[282],"description":"To protect its Trainer, it will expend all its psychic power to create a small black hole.","regulation_mark":"E","illustrator":"Sanosuke Sakuma","name_es":"Gardevoir"}'::jsonb),  -- Astral Radiance Trainer Gallery/TG05
    ('swsh10.5tg', 6, 'wyrdeer', 'wyrdeer', true, '{"category":"Pokemon","hp":140,"types":["Psychic"],"stage":"Stage1","evolve_from":"Stantler","retreat":2,"attacks":[{"cost":["Colorless","Colorless"],"name":"Paranormal","effect":"Si tienes la misma cantidad de cartas en tu mano que tu rival, este ataque hace 80 puntos de daño más.","damage":"40+"}],"abilities":[{"type":"Habilidad","name":"Marcha Apresurada","effect":"Una vez durante tu turno, puedes robar 1 carta."}],"weaknesses":[{"type":"Darkness","value":"×2"}],"resistances":[{"type":"Fighting","value":"-30"}],"dex_ids":[899],"description":"The black orbs shine with an uncanny light when the Pokémon is erecting invisible barriers. The fur shed from its beard retains heat well and is a highly useful material for winter clothing.","regulation_mark":"F","illustrator":"kirisAki","name_es":"Wyrdeer"}'::jsonb),  -- Astral Radiance Trainer Gallery/TG06
    ('swsh10.5tg', 7, 'falinks', 'falinks', true, '{"category":"Pokemon","hp":110,"types":["Fighting"],"stage":"Basic","retreat":2,"attacks":[{"cost":["Fighting","Colorless"],"name":"Escuadrón Golpe Fluido","effect":"Este ataque hace 20 puntos de daño por cada uno de tus Pokémon Golpe Fluido en juego.","damage":"20×"}],"weaknesses":[{"type":"Psychic","value":"×2"}],"dex_ids":[870],"description":"The six of them work together as one Pokémon. Teamwork is also their battle strategy, and they constantly change their formation as they fight.","regulation_mark":"E","illustrator":"Kinu Nishimura","name_es":"Falinks"}'::jsonb),  -- Astral Radiance Trainer Gallery/TG07
