    ('swsh11.5tg', 4, 'chandelure', 'chandelure', true, '{"category":"Pokemon","hp":150,"types":["Fire"],"stage":"Stage2","evolve_from":"Lampent","retreat":2,"attacks":[{"cost":["Fire","Colorless"],"name":"Explosión de Calor","damage":90}],"abilities":[{"type":"Habilidad","name":"Abrasamontañas","effect":"Cuando juegas este Pokémon de tu mano para hacer evolucionar a 1 de tus Pokémon durante tu turno, puedes descartar las 3 primeras cartas de la baraja de tu rival."}],"dex_ids":[609],"regulation_mark":"F","illustrator":"chibi","name_es":"Chandelure"}'::jsonb),  -- Lost Origin Trainer Gallery/TG04
