  ) as v(set_id, num, k, kes, unico, f)
 where c.market = 'WEST'
   and c.set_id = v.set_id
   and c.category is null
   and regexp_replace(immutable_unaccent(lower(c.name)), '[^a-z0-9]', '', 'g') in (v.k, v.kes)
   and ((case when length(regexp_replace(c.local_id, '\D', '', 'g')) between 1 and 9 then regexp_replace(c.local_id, '\D', '', 'g')::int end) = v.num or v.unico);

-- ── A7. Silver Tempest Trainer Gallery (30) ──────────────────────────
update public.tcg_cards c
   set category        = coalesce(c.category, v.f->>'category'),
       hp              = coalesce(c.hp, (v.f->>'hp')::int),
       types           = coalesce(c.types, (select array_agg(t) from jsonb_array_elements_text(v.f->'types') t)),
       stage           = coalesce(c.stage, v.f->>'stage'),
       evolve_from     = coalesce(c.evolve_from, v.f->>'evolve_from'),
       retreat         = coalesce(c.retreat, (v.f->>'retreat')::int),
       attacks         = coalesce(c.attacks, v.f->'attacks'),
       abilities       = coalesce(c.abilities, v.f->'abilities'),
       weaknesses      = coalesce(c.weaknesses, v.f->'weaknesses'),
       resistances     = coalesce(c.resistances, v.f->'resistances'),
       trainer_type    = coalesce(c.trainer_type, v.f->>'trainer_type'),
       energy_type     = coalesce(c.energy_type, v.f->>'energy_type'),
       suffix          = coalesce(c.suffix, v.f->>'suffix'),
       dex_ids         = case when coalesce(cardinality(c.dex_ids), 0) = 0
                              then coalesce((select array_agg(d::int) from jsonb_array_elements_text(v.f->'dex_ids') d), c.dex_ids)
                              else c.dex_ids end,
       regulation_mark = coalesce(c.regulation_mark, v.f->>'regulation_mark'),
       illustrator     = coalesce(c.illustrator, v.f->>'illustrator'),
       description     = coalesce(nullif(c.description, ''), v.f->>'description'),
       name_es         = coalesce(c.name_es, v.f->>'name_es')
  from (values
    ('swsh12.5tg', 1, 'braixen', 'braixen', true, '{"category":"Pokemon","hp":90,"types":["Fire"],"stage":"Stage1","evolve_from":"Fennekin","retreat":1,"attacks":[{"cost":["Fire"],"name":"Combustión","damage":30},{"cost":["Colorless","Colorless"],"name":"Desfile de Antorchas","effect":"Este ataque hace 60 puntos de daño por cada carta de Serena en tu pila de descartes.","damage":"60×"}],"weaknesses":[{"type":"Water","value":"×2"}],"dex_ids":[654],"description":"When the twig is plucked from its tail, friction sets the twig alight. The flame is used to send signals to its allies.","regulation_mark":"F","illustrator":"Naoki Saito","name_es":"Braixen"}'::jsonb),  -- Silver Tempest Trainer Gallery/TG01
    ('swsh12.5tg', 2, 'milotic', 'milotic', true, '{"category":"Pokemon","hp":130,"types":["Water"],"stage":"Stage1","evolve_from":"Feebas","retreat":2,"attacks":[{"cost":["Water"],"name":"Flecha de Agua","effect":"Este ataque hace 50 puntos de daño a 1 de los Pokémon de tu rival. (No apliques Debilidad y Resistencia a los Pokémon en Banca)."},{"cost":["Water","Colorless"],"name":"Onda Apacible","effect":"El Pokémon Activo de tu rival pasa a estar Dormido.","damage":60}],"weaknesses":[{"type":"Lightning","value":"×2"}],"dex_ids":[350],"description":"Milotic has provided inspiration to many artists. It has even been referred to as the most beautiful Pokémon of all.","regulation_mark":"F","illustrator":"chibi","name_es":"Milotic"}'::jsonb),  -- Silver Tempest Trainer Gallery/TG02
    ('swsh12.5tg', 3, 'flaaffy', 'flaaffy', true, '{"category":"Pokemon","hp":90,"types":["Lightning"],"stage":"Stage1","evolve_from":"Mareep","retreat":2,"attacks":[{"cost":["Lightning","Lightning","Colorless"],"name":"Bola Voltio","damage":50}],"abilities":[{"type":"Habilidad","name":"Dinamotor","effect":"Una vez durante tu turno (antes de tu ataque), puedes unir una carta de Energía Lightning de tu pila de descartes a 1 de tus Pokémon en Banca."}],"weaknesses":[{"type":"Fighting","value":"×2"}],"dex_ids":[180],"description":"It stores electricity in its fluffy fleece. If it stores up too much, it will start to go bald in those patches.","regulation_mark":"E","illustrator":"saino misaki","name_es":"Flaaffy"}'::jsonb),  -- Silver Tempest Trainer Gallery/TG03
    ('swsh12.5tg', 4, 'jynx', 'jynx', true, '{"category":"Pokemon","hp":100,"types":["Psychic"],"stage":"Basic","retreat":2,"attacks":[{"cost":["Colorless","Colorless"],"name":"Asalto Psíquico","effect":"Este ataque hace 10 puntos de daño más por cada contador de daño en el Pokémon Activo de tu rival.","damage":"10+"}],"abilities":[{"type":"Habilidad","name":"Labios Egoístas","effect":"Si este Pokémon queda Fuera de Combate por el daño de un ataque de los Pokémon V de tu rival, tu rival no puede coger ninguna carta de Premio por ello."}],"weaknesses":[{"type":"Darkness","value":"×2"}],"resistances":[{"type":"Fighting","value":"-30"}],"dex_ids":[124],"description":"In certain parts of Galar, Jynx was once feared and worshiped as the Queen of Ice.","regulation_mark":"F","illustrator":"HYOGONOSUKE","name_es":"Jynx"}'::jsonb),  -- Silver Tempest Trainer Gallery/TG04
    ('swsh12.5tg', 5, 'gardevoir', 'gardevoir', true, '{"category":"Pokemon","hp":150,"types":["Psychic"],"stage":"Stage2","evolve_from":"Kirlia","retreat":2,"attacks":[{"cost":["Psychic","Colorless"],"name":"Disparo Mágico","damage":120}],"abilities":[{"type":"Habilidad","name":"Refinamiento","effect":"Debes descartar 1 carta de tu mano para poder usar esta habilidad. Una vez durante tu turno, puedes robar 2 cartas."}],"weaknesses":[{"type":"Metal","value":"×2"}],"dex_ids":[282],"description":"It has the power to predict the future. Its power peaks when it is protecting its Trainer.","regulation_mark":"F","illustrator":"AKIRA EGAWA","name_es":"Gardevoir"}'::jsonb),  -- Silver Tempest Trainer Gallery/TG05
    ('swsh12.5tg', 6, 'malamar', 'malamar', true, '{"category":"Pokemon","hp":120,"types":["Psychic"],"stage":"Stage1","evolve_from":"Inkay","retreat":3,"attacks":[{"cost":["Psychic"],"name":"Tentáculos Golpe Fluido","effect":"Enseña cualquier cantidad de cartas de Golpe Fluido de tu mano. Este ataque hace 40 puntos de daño por cada carta que hayas enseñado de esta manera. Después, pon esas cartas en tu baraja y barájalas todas.","damage":"40×"}],"weaknesses":[{"type":"Darkness","value":"×2"}],"resistances":[{"type":"Fighting","value":"-30"}],"dex_ids":[687],"description":"It''s said that Malamar''s hypnotic powers played a role in certain history-changing events.","regulation_mark":"E","illustrator":"Fumie Kittaka","name_es":"Malamar"}'::jsonb),  -- Silver Tempest Trainer Gallery/TG06
    ('swsh12.5tg', 7, 'rockruff', 'rockruff', true, '{"category":"Pokemon","hp":70,"types":["Fighting"],"stage":"Basic","retreat":1,"attacks":[{"cost":["Fighting","Fighting"],"name":"Triturar","effect":"Lanza 1 moneda. Si sale cara, descarta 1 Energía del Pokémon Activo de tu rival.","damage":30}],"weaknesses":[{"type":"Grass","value":"×2"}],"dex_ids":[744],"description":"When it rubs the rocks on its neck against you, that''s proof of its love for you. However, the rocks are sharp, so the gesture is quite painful!","regulation_mark":"E","illustrator":"Hideki Ishikawa","name_es":"Rockruff"}'::jsonb),  -- Silver Tempest Trainer Gallery/TG07
    ('swsh12.5tg', 8, 'passimian', 'passimian', true, '{"category":"Pokemon","hp":110,"types":["Fighting"],"stage":"Basic","retreat":1,"attacks":[{"cost":["Fighting"],"name":"Lanzamiento","effect":"Este ataque hace 20 puntos de daño a 1 de los Pokémon de tu rival. (No apliques Debilidad y Resistencia a los Pokémon en Banca)."}],"abilities":[{"type":"Habilidad","name":"Entrenador de Lanzamiento","effect":"Los ataques de tus Pokémon Golpe Fluido hacen 30 puntos de daño más a los Pokémon V en Banca y Pokémon-GX en Banca de tu rival (antes de aplicar Debilidad y Resistencia). No puedes aplicar más de 1 habilidad Entrenador de Lanzamiento a la vez."}],"weaknesses":[{"type":"Psychic","value":"×2"}],"dex_ids":[766],"description":"Passimian live in groups of about 20, with each member performing an assigned role. Through cooperation, the group survives.","regulation_mark":"E","illustrator":"nagimiso","name_es":"Passimian"}'::jsonb),  -- Silver Tempest Trainer Gallery/TG08
    ('swsh12.5tg', 9, 'druddigon', 'druddigon', true, '{"category":"Pokemon","hp":120,"types":["Dragon"],"stage":"Basic","retreat":2,"attacks":[{"cost":["Fire","Water"],"name":"Desquite","effect":"Si alguno de tus Pokémon quedó Fuera de Combate por el daño de un ataque de los Pokémon de tu rival durante su último turno, este ataque hace 120 puntos de daño más.","damage":"40+"},{"cost":["Fire","Water","Colorless"],"name":"Garra Dragón","damage":120}],"dex_ids":[621],"description":"Druddigon are vicious and cunning. They take up residence in nests dug out by other Pokémon, treating the stolen nests as their own lairs.","regulation_mark":"E","illustrator":"Teeziro","name_es":"Druddigon"}'::jsonb),  -- Silver Tempest Trainer Gallery/TG09
