-- ── B. Las reimpresiones, copiadas de su impresión original ──────────
--
-- `objetivo`: lo que sigue sin categoría, con su nombre en clave (minúsculas,
-- sin tildes ni signos), los dígitos de su número, el «NNN/MMM» de un Prize
-- Pack partido en dos y el número escrito igual que otro set («SWSH111»,
-- «SVP 173» → «SVP173»; sin ceros delante de cada cifra).
-- `claves`: cada carta CON ficha, una fila por cada forma de su nombre
-- (`name`, `name_en`, `name_es`), para cruzar por igualdad y no evaluar
-- expresiones carta contra carta. Los Prize Pack no son origen de nada.
-- La prioridad: 1 mismo set y número; 2 el set de MMM cartas oficiales y el
-- número NNN; 3 el mismo número escrito igual. Se queda la MEJOR prioridad
-- de cada carta, y solo si a ese nivel todas las candidatas son la MISMA
-- impresión (mismo set y número): dos impresiones distintas son una duda,
-- y una duda no se rellena.
update public.tcg_cards c
   set category        = coalesce(c.category, e.category),
       hp              = coalesce(c.hp, e.hp),
       types           = coalesce(c.types, e.types),
       stage           = coalesce(c.stage, e.stage),
       evolve_from     = coalesce(c.evolve_from, e.evolve_from),
       retreat         = coalesce(c.retreat, e.retreat),
       attacks         = coalesce(c.attacks, e.attacks),
       abilities       = coalesce(c.abilities, e.abilities),
       weaknesses      = coalesce(c.weaknesses, e.weaknesses),
       resistances     = coalesce(c.resistances, e.resistances),
       trainer_type    = coalesce(c.trainer_type, e.trainer_type),
       energy_type     = coalesce(c.energy_type, e.energy_type),
       suffix          = coalesce(c.suffix, e.suffix),
       dex_ids         = case when coalesce(cardinality(c.dex_ids), 0) = 0 then coalesce(e.dex_ids, c.dex_ids) else c.dex_ids end,
       regulation_mark = coalesce(c.regulation_mark, e.regulation_mark),
       -- La rareza también: es la de la impresión que reimprime, y de ella
       -- sale «AS TÁCTICO» (una por mazo, `esAsTactico`).
       rarity          = coalesce(c.rarity, e.rarity),
       illustrator     = coalesce(c.illustrator, e.illustrator),
       description     = coalesce(nullif(c.description, ''), nullif(e.description, '')),
       name_es         = coalesce(c.name_es, e.name_es)
  from (
    with objetivo as (
      select t.id,
             t.set_id,
             regexp_replace(immutable_unaccent(lower(t.name)), '[^a-z0-9]', '', 'g') as k,
             case when length(regexp_replace(t.local_id, '\D', '', 'g')) between 1 and 9
                  then regexp_replace(t.local_id, '\D', '', 'g')::int end as n,
             (regexp_match(t.local_id, '^\s*0*(\d{1,6})\s*/\s*0*(\d{1,6})\s*$'))[1]::int as n1,
             (regexp_match(t.local_id, '^\s*0*(\d{1,6})\s*/\s*0*(\d{1,6})\s*$'))[2]::int as oficial,
             regexp_replace(upper(regexp_replace(t.local_id, '\s', '', 'g')), '(^|[^0-9])0+([0-9])', '\1\2', 'g') as l
        from public.tcg_cards t
       where t.market = 'WEST' and t.category is null
    ),
    claves as (
      select distinct g.id, x.k
        from public.tcg_cards g
        cross join lateral (values (g.name), (g.name_en), (g.name_es)) as nombres(nombre)
        cross join lateral (select regexp_replace(immutable_unaccent(lower(nombres.nombre)), '[^a-z0-9]', '', 'g') as k) as x
       where g.market = 'WEST' and g.category is not null and g.set_id not like 'tg-7%'
         and nombres.nombre is not null and x.k <> ''
    ),
    candidatas as (
      select o.id as destino,
             g.*,
             case when length(regexp_replace(g.local_id, '\D', '', 'g')) between 1 and 9
                  then regexp_replace(g.local_id, '\D', '', 'g')::int end as gn,
             case
               when g.set_id = o.set_id
                    and o.n = case when length(regexp_replace(g.local_id, '\D', '', 'g')) between 1 and 9
                                   then regexp_replace(g.local_id, '\D', '', 'g')::int end then 1
               when o.oficial is not null and s.card_count_official = o.oficial
                    and o.n1 = case when length(regexp_replace(g.local_id, '\D', '', 'g')) between 1 and 9
                                    then regexp_replace(g.local_id, '\D', '', 'g')::int end then 2
               when o.l = regexp_replace(upper(regexp_replace(g.local_id, '\s', '', 'g')), '(^|[^0-9])0+([0-9])', '\1\2', 'g') then 3
             end as prioridad
        from objetivo o
        join claves k on k.k = o.k
        join public.tcg_cards g on g.id = k.id and g.market = 'WEST'
        left join public.tcg_sets s on s.id = g.set_id and s.market = 'WEST'
    ),
    mejores as (
      select *, min(prioridad) over (partition by destino) as mejor
        from candidatas
       where prioridad is not null
    ),
    sin_duda as (
      select destino
        from mejores
       where prioridad = mejor
       group by destino
      having count(distinct set_id || '|' || coalesce(gn::text, local_id)) = 1
    )
    select distinct on (m.destino) m.*
      from mejores m
      join sin_duda d using (destino)
     where m.prioridad = m.mejor
     order by m.destino,
              (m.attacks is null and m.trainer_type is null and m.energy_type is null),
              (m.id like 'tcggo-%' or m.id like 'mano-%'),
              (m.detalle_lang is distinct from 'es'),
              m.id
  ) e
 where c.id = e.destino
   and c.market = 'WEST'
   and c.category is null;

-- ── C1. Entrenadores y energías especiales por su nombre ─────────────
--
-- Lo que B no pudo casar por número («Energy Retrieval» con un 106 que no es
-- el suyo, el «Boss's Orders 172/193» que nuestra Paldea Evolved no numera
-- así). Un Entrenador se llama igual en todas sus impresiones y hace lo
-- mismo, así que basta con que TODAS las cartas de ese nombre sean de la
-- misma clase y, las que dicen subclase, la misma (canónica: «Objeto» es
-- «Item»). Un Pokémon no entra aquí: dos «Pikachu» no son la misma carta.
update public.tcg_cards c
   set category     = coalesce(c.category, e.category),
       trainer_type = coalesce(c.trainer_type, e.trainer_type),
       energy_type  = coalesce(c.energy_type, e.energy_type),
       suffix       = coalesce(c.suffix, e.suffix),
       rarity       = coalesce(c.rarity, case when e.rarity ~* 'ace ?spec|as t[aá]ctico' then e.rarity end),
       description  = coalesce(nullif(c.description, ''), nullif(e.description, '')),
       name_es      = coalesce(c.name_es, e.name_es)
  from (
    with objetivo as (
      select t.id, regexp_replace(immutable_unaccent(lower(t.name)), '[^a-z0-9]', '', 'g') as k
        from public.tcg_cards t
       where t.market = 'WEST' and t.category is null
    ),
    claves as (
      select distinct g.id, x.k
        from public.tcg_cards g
        cross join lateral (values (g.name), (g.name_en), (g.name_es)) as nombres(nombre)
        cross join lateral (select regexp_replace(immutable_unaccent(lower(nombres.nombre)), '[^a-z0-9]', '', 'g') as k) as x
       where g.market = 'WEST' and g.category is not null and g.set_id not like 'tg-7%'
         and nombres.nombre is not null and x.k <> ''
    ),
    candidatas as (
      select o.id as destino, g.*,
             case when g.category in ('Pokemon', 'Pokémon') then 'Pokemon'
                  when g.category in ('Trainer', 'Entrenador') then 'Trainer'
                  when g.category in ('Energy', 'Energía', 'Energia') then 'Energy'
                  else g.category end as clase,
             case when g.trainer_type in ('Item', 'Objeto') then 'Item'
                  when g.trainer_type in ('Supporter', 'Partidario') then 'Supporter'
                  when g.trainer_type in ('Stadium', 'Estadio') then 'Stadium'
                  when g.trainer_type in ('Tool', 'Herramienta', 'Pokémon Tool', 'Herramienta Pokémon') then 'Tool'
                  when g.energy_type in ('Special', 'Especial') then 'Special'
                  when g.energy_type in ('Normal', 'Basic', 'Básico', 'Básica', 'Basico', 'Basica') then 'Normal'
                  else coalesce(g.trainer_type, g.energy_type) end as subclase
        from objetivo o
        join claves k on k.k = o.k
        join public.tcg_cards g on g.id = k.id and g.market = 'WEST'
    ),
    sin_duda as (
      select destino
        from candidatas
       group by destino
      having count(distinct clase) = 1
         and bool_and(clase in ('Trainer', 'Energy'))
         -- Las impresiones viejas no traen subclase («Energy Retrieval» de
         -- Base Set, «Boss's Orders» de la Classic Collection): no cuentan
         -- como otra opinión, pero las que la traen tienen que coincidir.
         and count(distinct subclase) <= 1
    )
    select distinct on (m.destino) m.*
      from candidatas m
      join sin_duda d using (destino)
     order by m.destino, (m.subclase is null), (m.id like 'tcggo-%' or m.id like 'mano-%'), (m.detalle_lang is distinct from 'es'), m.id
  ) e
 where c.id = e.destino
   and c.market = 'WEST'
   and c.category is null;

-- ── C2. Las energías básicas, por su nombre ──────────────────────────
--
-- «Basic Grass Energy», «Grass Energy», «Lightning Energy»… de los Prize
-- Pack y los kits: como las de SVE, Energía «Normal» y sin tipo en la fila
-- (el constructor y la mesa la reconocen por el nombre, `esNombreDeEnergiaBasica`).
update public.tcg_cards c
   set category = 'Energy',
       energy_type = coalesce(c.energy_type, 'Normal')
 where c.market = 'WEST'
   and c.category is null
   and lower(btrim(regexp_replace(c.name, '\s+', ' ', 'g'))) ~ '^(basic )?(grass|fire|water|lightning|psychic|fighting|darkness|metal|fairy) energy$';

-- ── Lo que haya quedado sin ficha ────────────────────────────────────
--
-- Debería salir vacío o casi. Si sale algo, es una carta que ni TCGdex ni
-- nuestro catálogo saben qué es: se corrige a mano en /admin → Catálogo.
select set_id, count(*) as sin_ficha, string_agg(local_id || ' ' || name, ' · ' order by local_id) as cuales
  from public.tcg_cards
 where market = 'WEST' and category is null
 group by set_id
 order by count(*) desc;
